def transform(grid):
    from collections import Counter, deque

    g = [row[:] for row in grid]
    H, W = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    def components(color):
        seen = set()
        result = []
        for r in range(H):
            for c in range(W):
                if g[r][c] != color or (r, c) in seen:
                    continue
                q = [(r, c)]
                seen.add((r, c))
                comp = []
                while q:
                    x, y = q.pop()
                    comp.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < H and 0 <= ny < W and
                                g[nx][ny] == color and (nx, ny) not in seen):
                            seen.add((nx, ny))
                            q.append((nx, ny))
                result.append(comp)
        return result

    # Find the prominent L-shaped component and its corner.
    marker = None
    best = None
    for color in set(v for row in g for v in row):
        if color == bg:
            continue
        for comp in components(color):
            rs = [p[0] for p in comp]
            cs = [p[1] for p in comp]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            if r1 - r0 < 3 or c1 - c0 < 3:
                continue
            for cr in (r0, r1):
                for cc in (c0, c1):
                    hlen = sum((cr, c) in set(comp) for c in range(c0, c1 + 1))
                    vlen = sum((r, cc) in set(comp) for r in range(r0, r1 + 1))
                    # Arms must meet at this bounding-box corner.
                    if hlen < 5 or vlen < 4:
                        continue
                    score = hlen + vlen
                    if best is None or score > best[0]:
                        best = (score, color, comp, cr, cc, 1 if cc == c0 else -1)

    if best is None:
        return g

    _, marker_color, marker_comp, hr, vc, hdir = best
    marker_set = set(marker_comp)

    # Components on the upper side of the horizontal arm, across the vertical
    # stem from the arm's direction, are possible targets.
    candidates = []
    for color in set(v for row in g for v in row):
        if color == bg:
            continue
        for comp in components(color):
            if set(comp) == marker_set:
                continue
            rs = [p[0] for p in comp]
            cs = [p[1] for p in comp]
            if max(rs) > hr:
                continue

            center_c = sum(cs) / len(cs)
            if hdir == 1:  # horizontal arm points right
                side_ok = center_c < vc + 0.2 or min(cs) == vc
            else:          # horizontal arm points left
                side_ok = center_c > vc - 0.2 or max(cs) == vc
            if not side_ok:
                continue

            # A straight object continuing the horizontal row is a strong
            # match when it lies beyond the corner.
            on_row = all(r == hr for r, c in comp)
            if hdir == -1 and on_row and min(cs) > vc:
                priority = 0
            else:
                priority = 1

            dist = min(abs(r - rr) + abs(c - cc)
                       for r, c in comp for rr, cc in marker_set)
            candidates.append((priority, dist, -len(comp), comp))

    if not candidates:
        return g

    target = min(candidates, key=lambda x: (x[0], x[1], x[2]))[3]
    for r, c in target:
        g[r][c] = marker_color
    return g
